+    throw new RangeError("invalid allocation input");
+  }
+
+  const values = [];
+  let sum = 0n;
+  for (let i = 0; i < weights.length; i++) {
+    if (!Object.prototype.hasOwnProperty.call(weights, i) || !Number.isSafeInteger(weights[i]) || weights[i] < 0) {
